/// <summary>
/// MPJ-3746 - KScerri - 07/05/2021
/// The <c>METPaymTermForm_Extension</c> class is an extension of the Payterm form to disable MET extension on PayTerm
/// table.
/// </summary>
[ExtensionOf(FormStr(PaymTerm))]
public final class METPaymTermForm_Extension 
{
    #ISOCountryRegionCodes

}

Method.Source:
    /// <summary>
    /// MPJ-3746 - KScerri - 07/05/2021
    /// Disabling extention field if payment method is 'cutoff day'
    /// </summary>
    void enableFields()
    {
        boolean isJapanRegion = SysCountryRegionCode::isLegalEntityInCountryRegion([#ISOJP]);

        next enableFields();

        if (!isJapanRegion)
        {
            payment_ds.object(fieldNum(PaymTerm, METCutOffDays)).enabled(payment.PaymMethod != NetCurrent::CutOffDate);
        }
    }
